#pragma once

// The GUI.Forms Gallery's compiled view of manifests/controls.json. The array
// in gallery_catalog.inc is generated by `python3 tools/control_registry.py
// emit-cpp`; the Gallery derives its navigation groups and per-page header
// strips from it, so the program describes exactly the registry it ships with.
// Demo-facing code only: no host, renderer, or platform type appears here.

#include <array>
#include <cstddef>
#include <string_view>

namespace gui_forms::gallery {

struct CatalogEntry final {
    std::string_view id;            // kebab-case registry id, e.g. "track-bar"
    std::string_view type;          // public C++ type name, e.g. "TrackBar"
    std::string_view header;        // path relative to include/
    std::string_view category;      // one of catalog_categories
    std::string_view purpose;       // one sentence
    std::string_view winforms;      // WinForms counterpart or "GUI.Forms-only"
    std::string_view status;        // stable | provisional | lab
    std::string_view gallery_page;  // Gallery page id, or empty when none demonstrates it
};

#include "gallery_catalog.inc"

[[nodiscard]] constexpr const CatalogEntry* find_catalog_entry(std::string_view id) noexcept
{
    for (const CatalogEntry& entry : control_catalog) {
        if (entry.id == id) {
            return &entry;
        }
    }
    return nullptr;
}

[[nodiscard]] consteval bool catalog_ids_are_unique()
{
    for (std::size_t left = 0; left < control_catalog.size(); ++left) {
        if (control_catalog[left].id.empty() || control_catalog[left].type.empty()) {
            return false;
        }
        for (std::size_t right = left + 1; right < control_catalog.size(); ++right) {
            if (control_catalog[left].id == control_catalog[right].id ||
                control_catalog[left].type == control_catalog[right].type) {
                return false;
            }
        }
    }
    return true;
}

[[nodiscard]] consteval bool catalog_categories_resolve()
{
    for (const CatalogEntry& entry : control_catalog) {
        bool found = false;
        for (const std::string_view category : catalog_categories) {
            found = found || category == entry.category;
        }
        if (!found) {
            return false;
        }
    }
    return true;
}

static_assert(catalog_ids_are_unique());
static_assert(catalog_categories_resolve());

}  // namespace gui_forms::gallery
